#!/usr/bin/env python3
import pathlib
import sys

root = pathlib.Path(sys.argv[1])
path_rs = root / "src/sources/path.rs"
source_rs = root / "src/sources/git/source.rs"
s = path_rs.read_text()

# Add per-source warm-index state. The index itself is generated by Cargo's
# existing full discovery path in a previous process.
old_fields = """    /// Avoid redundant unused package warnings
    warned_duplicate: RefCell<HashSet<PackageId>>,
    gctx: &'gctx GlobalContext,
}"""
new_fields = """    /// Avoid redundant unused package warnings
    warned_duplicate: RefCell<HashSet<PackageId>>,
    /// Experimental cargo#14395 warm index: package name -> candidate roots.
    manifest_index: RefCell<Option<HashMap<String, Vec<PathBuf>>>>,
    /// Paths already parsed through the warm index, including nested path deps.
    indexed_visited: RefCell<HashSet<PathBuf>>,
    gctx: &'gctx GlobalContext,
}"""
assert old_fields in s
s = s.replace(old_fields, new_fields, 1)

old_new = """            packages: Default::default(),
            warned_duplicate: Default::default(),
            gctx,
"""
new_new = """            packages: Default::default(),
            warned_duplicate: Default::default(),
            manifest_index: Default::default(),
            indexed_visited: Default::default(),
            gctx,
"""
assert old_new in s
s = s.replace(old_new, new_new, 1)

# Replace the start of query with a warm-index fast path. If the sidecar is
# missing or unreadable, current full discovery remains the fallback.
old_query = """    ) -> CargoResult<()> {
        self.load()?;
        for s in self
            .packages
            .borrow()
            .iter()
            .filter(|(pkg_id, _)| pkg_id.name() == dep.package_name())
            .map(|(pkg_id, pkgs)| {
                first_package(
                    *pkg_id,
                    pkgs,
                    &mut self.warned_duplicate.borrow_mut(),
                    self.gctx,
                )
            })
            .map(|p| p.summary())
        {
            let matched = match kind {
                QueryKind::Exact | QueryKind::RejectedVersions => dep.matches(s),
                QueryKind::AlternativeNames => true,
                QueryKind::Normalized => dep.matches(s),
            };
            if matched {
                f(IndexSummary::Candidate(s.clone()))
            }
        }
        Ok(())
    }
"""
new_query = """    ) -> CargoResult<()> {
        if !self.loaded.get()
            && self.source_id.is_git()
            && std::env::var_os(\"CARGO_GIT_MANIFEST_INDEX_USE\").is_some()
        {
            if self.manifest_index.borrow().is_none() {
                let index_path = self.path.join(\".cargo-manifest-index-experiment\");
                if let Ok(contents) = fs::read_to_string(&index_path) {
                    let mut index = HashMap::<String, Vec<PathBuf>>::default();
                    for line in contents.lines() {
                        let Some((name, rel)) = line.split_once('\\t') else {
                            continue;
                        };
                        if name.is_empty() || rel.is_empty() {
                            continue;
                        }
                        index
                            .entry(name.to_owned())
                            .or_default()
                            .push(PathBuf::from(rel));
                    }
                    if !index.is_empty() {
                        self.manifest_index.replace(Some(index));
                    }
                }
            }

            let package_name = dep.package_name().to_string();
            let candidates = self
                .manifest_index
                .borrow()
                .as_ref()
                .map(|index| index.get(&package_name).cloned());

            if let Some(candidates) = candidates {
                let candidates = candidates.unwrap_or_default();
                let mut discovered = HashMap::default();
                let mut errors = Vec::<anyhow::Error>::new();
                let before = self.indexed_visited.borrow().len();
                {
                    let mut visited = self.indexed_visited.borrow_mut();
                    for rel in &candidates {
                        let dir = if rel == Path::new(\".\") {
                            self.path.clone()
                        } else {
                            self.path.join(rel)
                        };
                        if has_manifest(&dir) {
                            read_nested_packages(
                                &dir,
                                &mut discovered,
                                self.source_id,
                                self.gctx,
                                &mut visited,
                                &mut errors,
                            )?;
                        }
                    }
                }

                if !discovered.is_empty() {
                    let mut packages = self.packages.borrow_mut();
                    for (pkg_id, mut found) in discovered {
                        packages.entry(pkg_id).or_default().append(&mut found);
                    }
                }

                if std::env::var_os(\"CARGO_GIT_MANIFEST_INDEX_STATS\").is_some() {
                    eprintln!(
                        \"cargo-manifest-index query={} candidates={} newly_parsed={} total_parsed={}\",
                        package_name,
                        candidates.len(),
                        self.indexed_visited.borrow().len().saturating_sub(before),
                        self.indexed_visited.borrow().len(),
                    );
                }

                for s in self
                    .packages
                    .borrow()
                    .iter()
                    .filter(|(pkg_id, _)| pkg_id.name() == dep.package_name())
                    .map(|(pkg_id, pkgs)| {
                        first_package(
                            *pkg_id,
                            pkgs,
                            &mut self.warned_duplicate.borrow_mut(),
                            self.gctx,
                        )
                    })
                    .map(|p| p.summary())
                {
                    let matched = match kind {
                        QueryKind::Exact | QueryKind::RejectedVersions => dep.matches(s),
                        QueryKind::AlternativeNames => true,
                        QueryKind::Normalized => dep.matches(s),
                    };
                    if matched {
                        f(IndexSummary::Candidate(s.clone()))
                    }
                }
                return Ok(());
            }
        }

        self.load()?;
        for s in self
            .packages
            .borrow()
            .iter()
            .filter(|(pkg_id, _)| pkg_id.name() == dep.package_name())
            .map(|(pkg_id, pkgs)| {
                first_package(
                    *pkg_id,
                    pkgs,
                    &mut self.warned_duplicate.borrow_mut(),
                    self.gctx,
                )
            })
            .map(|p| p.summary())
        {
            let matched = match kind {
                QueryKind::Exact | QueryKind::RejectedVersions => dep.matches(s),
                QueryKind::AlternativeNames => true,
                QueryKind::Normalized => dep.matches(s),
            };
            if matched {
                f(IndexSummary::Candidate(s.clone()))
            }
        }
        Ok(())
    }
"""
# There are two Source::query impls in this file; target the RecursivePathSource
# one by anchoring after its impl declaration.
anchor = "impl<'gctx> Source for RecursivePathSource<'gctx> {"
pos = s.index(anchor)
qpos = s.index(old_query, pos)
s = s[:qpos] + s[qpos:].replace(old_query, new_query, 1)

# Do not force a full scan from download() if query() already materialized the
# selected package through the index.
old_download = """    async fn download(&self, id: PackageId) -> CargoResult<MaybePackage> {
        trace!(\"getting packages; id={}\", id);
        self.load()?;
        let pkgs = self.packages.borrow();
        let pkg = pkgs.get(&id);
"""
new_download = """    async fn download(&self, id: PackageId) -> CargoResult<MaybePackage> {
        trace!(\"getting packages; id={}\", id);
        {
            let pkgs = self.packages.borrow();
            if let Some(found) = pkgs.get(&id) {
                return Ok(MaybePackage::Ready(
                    first_package(
                        id,
                        found,
                        &mut self.warned_duplicate.borrow_mut(),
                        self.gctx,
                    )
                    .clone(),
                ));
            }
        }
        self.load()?;
        let pkgs = self.packages.borrow();
        let pkg = pkgs.get(&id);
"""
dpos = s.index(old_download, s.index(anchor))
s = s[:dpos] + s[dpos:].replace(old_download, new_download, 1)

# After the existing, correctness-authoritative full scan, write one compact
# package-name -> relative-root index for the exact checkout.
old_return = """    } else {
        Ok(all_packages)
    }
}

fn nested_paths"""
new_return = """    } else {
        if source_id.is_git()
            && std::env::var_os(\"CARGO_GIT_MANIFEST_INDEX_BUILD\").is_some()
        {
            let mut lines = Vec::new();
            for (pkg_id, packages) in &all_packages {
                for pkg in packages {
                    if let Ok(rel) = pkg.root().strip_prefix(path) {
                        let rel = if rel.as_os_str().is_empty() {
                            \".\".to_owned()
                        } else {
                            rel.to_string_lossy().into_owned()
                        };
                        lines.push(format!(\"{}\\t{}\", pkg_id.name(), rel));
                    }
                }
            }
            lines.sort();
            lines.dedup();
            let index_path = path.join(\".cargo-manifest-index-experiment\");
            if let Err(err) = fs::write(&index_path, lines.join(\"\\n\") + \"\\n\") {
                warn!(\"failed to write manifest index {}: {}\", index_path.display(), err);
            }
        }
        Ok(all_packages)
    }
}

fn nested_paths"""
assert old_return in s
s = s.replace(old_return, new_return, 1)
path_rs.write_text(s)

# GitSource currently eagerly calls RecursivePathSource::load() during update,
# before the resolver has a package-name query. Skip that eager load only on
# the experiment's warm-index path; missing indexes still fall back in query().
g = source_rs.read_text()
old_eager = """        self.locked_rev.replace(Revision::Locked(actual_rev));
        self.path_source.borrow().as_ref().unwrap().load()?;

        self.mark_used()?;"""
new_eager = """        self.locked_rev.replace(Revision::Locked(actual_rev));
        if std::env::var_os(\"CARGO_GIT_MANIFEST_INDEX_USE\").is_none() {
            self.path_source.borrow().as_ref().unwrap().load()?;
        }

        self.mark_used()?;"""
assert old_eager in g
g = g.replace(old_eager, new_eager, 1)
source_rs.write_text(g)

print("generated realistic warm git manifest index variant")
